<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$next=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM sinistres')->fetchColumn();$numero='SIN-'.date('Y').'-'.str_pad((string)$next,4,'0',STR_PAD_LEFT);$db->prepare("INSERT INTO sinistres(contrat_id,gestionnaire_id,numero_sinistre,date_survenance,type_sinistre,description,montant_estime,commentaire_accompagnement) VALUES(?,?,?,?,?,?,?,?)")->execute([(int)$_POST['contrat_id'],$_SESSION['user']['id'],$numero,$_POST['date_survenance'],trim($_POST['type_sinistre']),trim($_POST['description']),$_POST['montant_estime']?:null,trim($_POST['commentaire'])?:null]);audit('DECLARATION','sinistre',(int)$db->lastInsertId());flash('success','Sinistre déclaré.');redirect('sinistres/index.php');}$contracts=$db->query("SELECT id,numero_police FROM contrats WHERE statut='actif' ORDER BY numero_police")->fetchAll();$rows=$db->query("SELECT s.*,c.numero_police FROM sinistres s JOIN contrats c ON c.id=s.contrat_id ORDER BY s.date_declaration DESC")->fetchAll();$title='Sinistres';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Accompagnement des sinistres</h1><p class="text-secondary">Déclaration et suivi client</p></div></div><form method="post" class="card card-body mb-4"><?= csrf_field() ?><h2 class="h5">Déclarer un sinistre</h2><div class="row g-2"><div class="col-md-3"><select class="form-select" name="contrat_id" required><?php foreach($contracts as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['numero_police']) ?></option><?php endforeach ?></select></div><div class="col-md-2"><input type="date" class="form-control" name="date_survenance" required></div><div class="col-md-3"><input class="form-control" name="type_sinistre" placeholder="Type de sinistre" required></div><div class="col-md-2"><input type="number" class="form-control" name="montant_estime" placeholder="Montant estimé"></div><div class="col-md-2"><button class="btn btn-primary w-100">Déclarer</button></div><div class="col-md-6"><textarea class="form-control" name="description" placeholder="Description" required></textarea></div><div class="col-md-6"><textarea class="form-control" name="commentaire" placeholder="Accompagnement prévu"></textarea></div></div></form><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Numéro</th><th>Police</th><th>Survenance</th><th>Type</th><th>Montant</th><th>Statut</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['numero_sinistre']) ?></td><td><?= e($r['numero_police']) ?></td><td><?= e($r['date_survenance']) ?></td><td><?= e($r['type_sinistre']) ?></td><td><?= number_format((float)$r['montant_estime'],0,',',' ') ?></td><td><?= e($r['statut']) ?></td></tr><?php endforeach ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
